window.catalogOffers=[];window.onlyPriced=false;let priceChecked='',priceLoaded=false;const money=n=>new Intl.NumberFormat('sv-SE',{maximumFractionDigits:2}).format(n)+' kr';const stamp=s=>new Date(s).toLocaleString('sv-SE',{timeZone:'Europe/Stockholm',dateStyle:'short',timeStyle:'short'});const live=o=>!o.endAt||Date.parse(o.endAt)>Date.now();const total=o=>o.shipping===null?null:o.price+o.shipping+(o.fee||0);const eligible=o=>o.kind==='fixed'&&o.weight&&o.pack!=='Ej angiven'&&['Ny','Oanvänt'].includes(o.condition)&&total(o)!==null;
// Lägsta jämförbara pris (inkl. frakt och köparskydd, räknat per kg) och största rabatt per färg.
window.priceIndex=new Map();
function buildPriceIndex(){const idx=new Map();for(const o of window.catalogOffers){if(!live(o))continue;let e=idx.get(o.key);if(!e){e={best:null,deal:null};idx.set(o.key,e)}if(eligible(o)){const perKg=total(o)/o.weight*1000;if(!e.best||perKg<e.best.perKg)e.best={o,perKg,total:total(o)}}if(o.kind==='fixed'&&o.discount>0&&(!e.deal||o.discount>e.deal.o.discount))e.deal={o}}window.priceIndex=idx}
window.priceInfo=key=>window.priceIndex.get(key)||null;
const regularNote=o=>o.regularSource==='butik'?'ordinarie pris enligt butiken':'typiskt pris senaste 30 dagarna';
window.priceLine=d=>{const e=window.priceInfo(ownedKey(d));if(!e||(!e.best&&!e.deal))return priceLoaded?'<p class="price-line muted">Inget jämförbart pris just nu</p>':'';let h='';if(e.best){const o=e.best.o;h+=`<p class="price-line"><span>Lägsta pris</span><strong>${money(e.best.total)}</strong><small>${esc(o.pack)} ${o.weight>=1000?(o.weight/1000).toLocaleString('sv-SE')+' kg':o.weight+' g'}${o.weight!==1000?' · '+money(Math.round(e.best.perKg))+'/kg':''} · inkl. frakt · ${esc(o.shop.split(' · ')[0])}</small></p>`}if(e.deal){const o=e.deal.o;h+=`<p class="deal-line" title="${esc(regularNote(o))}"><span class="deal-badge">−${o.discount} %</span> ${money(o.price)} <s>${money(o.regular)}</s> <small>${esc(o.shop.split(' · ')[0])}</small></p>`}return h};
function openPrices(key){const d=data.find(x=>ownedKey(x)===key);if(!d)return;let os=window.catalogOffers.filter(o=>o.key===key&&live(o)),expired=window.catalogOffers.filter(o=>o.key===key&&!live(o)).length;let groups=new Map();os.forEach(o=>{let g=o.kind==='auction'?'Auktioner · inte fasta köppriser':`${o.pack} · ${o.weight?o.weight+' g':'vikt ej verifierad'}`;if(!groups.has(g))groups.set(g,[]);groups.get(g).push(o)});let days=(Date.now()-Date.parse(priceChecked))/86400000;
let content=`<h2 id="priceTitle">${esc(d.type)} · ${esc(d.name)}</h2><p>Färgnummer ${esc(d.code||'ej angivet')} · Priser i SEK, inklusive moms där tillämpligt.<br>Sökning: ${priceChecked?stamp(priceChecked):'läses in'}. ${days>1?'Äldre prisuppgifter — kontrollera pris och lager hos säljaren.':'Kontrollera slutpris och lager innan köp.'}</p><p style="margin-top:10px">Jämförelsen gäller en förpackning med billigaste angivna frakt inom Sverige. Samfrakt, mängdrabatter och rabattkoder ingår inte. Refill och spole jämförs var för sig. Bambu Lab EU:s priser är i euro och räknas om till kronor med dagens växelkurs; frakt visas i deras kassa.</p>`;
if(!os.length)content+=`<div class="offer"><b>${priceLoaded?'Inget verifierat erbjudande för den här färgen':'Prisuppgifterna läses in'}</b><p>${expired?'Tidigare Tradera-annonser har passerat sluttiden. ':''}Använd länkarna nedan för att söka vidare.</p></div>`;
for(let [g,rows] of groups){rows.sort((a,b)=>(total(a)??Infinity)-(total(b)??Infinity));let comparable=rows.filter(eligible),best=comparable.length?Math.min(...comparable.map(total)):null;content+=`<h3 class="price-group">${esc(g)}</h3>`;for(let o of rows){let low=eligible(o)&&total(o)===best;content+=`<article class="offer ${low?'best':''}">${low?`<div class="best-label">${comparable.length>1?'Lägst hittat bland kontrollerade erbjudanden':'Enda jämförbara erbjudandet hittat'}${days>1?' · äldre pris':''}</div>`:''}<div class="offer-head"><div><a href="${esc(safeUrl(o.url))}" target="_blank" rel="noopener">${esc(o.shop)} ↗</a><small>${esc(o.title)}</small></div><strong>${money(total(o)??o.price)}</strong></div>${o.discount?`<p class="deal-line"><span class="deal-badge">−${o.discount} %</span> Varupris ${money(o.price)} mot ordinarie <s>${money(o.regular)}</s> <small>(${esc(regularNote(o))})</small></p>`:''}<small>${o.kind==='auction'?'Bud/utropspris':'Varupris'} ${money(o.price)} + ${o.shipping===null?'frakt ej verifierad':money(o.shipping)+' frakt'}${o.fee?' + '+money(o.fee)+' köparskydd':''}. ${total(o)!==null?'Summan ovan inkluderar dessa kostnader.':'Summan ovan saknar frakt.'}<br>${esc(o.condition)} · ${esc(o.sourceNote)} ${esc(o.shippingNote)}${o.endAt?'<br>Annonsen slutar '+stamp(o.endAt):''}<br>Kontrollerad ${stamp(o.checkedAt)}</small></article>`}}
let q=encodeURIComponent('Bambu Lab '+d.type+' '+d.name.replace(/^Matte |^ABS /,''));let eu=d.source.replace('us.store.bambulab.com','eu.store.bambulab.com');content+=`<div class="price-links"><a href="https://www.tradera.com/search?q=${q}" target="_blank" rel="noopener">Sök färgen på Tradera ↗</a><a href="https://www.prisjakt.nu/search?search=${q}" target="_blank" rel="noopener">Sök på Prisjakt ↗</a><a href="${esc(safeUrl(eu))}" target="_blank" rel="noopener">Bambu Lab EU · kontrollera pris ↗</a></div><p style="margin-top:15px">Söklänkarna är hjälp för fortsatt sökning, inte verifierade erbjudanden. Vi kan inte garantera marknadens lägsta pris eller full täckning av alla svenska butiker.</p>`;$('#priceContent').innerHTML=content;if(!$('#priceDialog').open)$('#priceDialog').showModal();}
$('#results').addEventListener('click',e=>{let b=e.target.closest('[data-prices]');if(b)openPrices(b.dataset.prices)});$('#closePrices').onclick=()=>$('#priceDialog').close();$('#priceFilter').onclick=()=>{window.onlyPriced=!window.onlyPriced;$('#priceFilter').setAttribute('aria-pressed',window.onlyPriced);$('#priceFilter').classList.toggle('active',window.onlyPriced);render()};$('#dealFilter').onclick=()=>{window.onlyDeals=!window.onlyDeals;$('#dealFilter').setAttribute('aria-pressed',window.onlyDeals);$('#dealFilter').classList.toggle('active',window.onlyDeals);if(window.onlyDeals&&['type','name','code'].includes($('#sort').value))$('#sort').value='discount';render()};fetch('offers.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(p=>{window.catalogOffers=p.offers;priceChecked=p.checkedAt;priceLoaded=true;buildPriceIndex();$('#priceCoverage').textContent=`${new Set(p.offers.filter(live).map(o=>o.key)).size} färger med prisuppgifter · ${[...window.priceIndex.values()].filter(e=>e.deal).length} med rabatt just nu · sökta ${stamp(priceChecked)}.`;render()}).catch(()=>{$('#priceCoverage').textContent='Prisuppgifterna kunde inte laddas. Försök ladda om sidan.'});
